    /**
 * <div id="function.bcmul" class="refentry"> <div class="refnamediv">  <h1 class="refname">bcmul</h1>  <p class="verinfo">(PHP 4, PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">bcmul</span> — <span class="dc-title">两个任意精度数字乘法计算</span></p> </div>  <div class="refsect1 description" id="refsect1-function.bcmul-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bcmul</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num1</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num2</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   <span class="parameter" style="color:#3A95FF">num1</span> 乘以 <span class="parameter" style="color:#3A95FF">num2</span>。  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bcmul-parameters">  <h3 class="title">参数</h3><p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">num1</span></dt>     <dd>      <p class="para">       左操作数，字符串类型。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">num2</span></dt>     <dd>      <p class="para">       右操作数，字符串类型。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>     <dd>      <span class="simpara">       此参数用于设置结果小数点后的位数。       如果为 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>，则默认为使用 <span class="function">{@link bcscale()}</span> 设置的默认精度，       或者回退到 <a href="https://php.net/manual/zh/bc.configuration.php#ini.bcmath.scale" class="link"><span class="literal">bcmath.scale</span></a> INI 指令的值。      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.bcmul-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   返回字符串类型的结果。  </p> </div> <div class="refsect1 errors" id="refsect1-function.bcmul-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   此函数在下列情况下抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>：   </p><ul class="simplelist">    <li>     <span class="parameter" style="color:#3A95FF">num1</span> 或 <span class="parameter" style="color:#3A95FF">num2</span> 不是格式正确的 BCMath 数字字符串。    </li>    <li>     <span class="parameter" style="color:#3A95FF">scale</span> 超出有效范围。    </li>   </ul>   </div> <div class="refsect1 changelog" id="refsect1-function.bcmul-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       现在 <span class="parameter" style="color:#3A95FF">scale</span> 可以为 null。      </td>     </tr>     <tr>      <td>7.3.0</td>      <td>       现在 <span class="function"><strong style="color:#CC7832">bcmul()</strong></span> 可以按想要的小数点位数返回数字。       而之前，返回的数字会忽略尾随零（trailing decimal zeroes）。      </td>     </tr>    </tbody>     </table> </div>  <div class="refsect1 examples" id="refsect1-function.bcmul-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">bcmul()</strong></span> 示例</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">bcmul</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.34747474747'</span><span style="color: #007700">, </span><span style="color: #DD0000">'35'</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">); </span><span style="color: #FF8000">// 47.161<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">bcmul</span><span style="color: #007700">(</span><span style="color: #DD0000">'2'</span><span style="color: #007700">, </span><span style="color: #DD0000">'4'</span><span style="color: #007700">); </span><span style="color: #FF8000">// 8<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 notes" id="refsect1-function.bcmul-notes">  <h3 class="title">注释</h3>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    PHP 7.3.0 之前，<span class="function"><strong style="color:#CC7832">bcmul()</strong></span> 返回的结果中小数位数可能比 <span class="parameter" style="color:#3A95FF">scale</span>    参数指定的少。只有当结果不需要 <span class="parameter" style="color:#3A95FF">scale</span> 允许的所有精度时，才会发生这种情况。例如：    </p><div class="example" id="example-2">     <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">bcmul()</strong></span> 进位制示例</strong></p>     <div class="example-contents">      <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">bcmul</span><span style="color: #007700">(</span><span style="color: #DD0000">'5'</span><span style="color: #007700">, </span><span style="color: #DD0000">'2'</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">);     </span><span style="color: #FF8000">// 打印“10”而不是“10.00”<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>     </div>    </div>     </blockquote> </div>  <div class="refsect1 seealso" id="refsect1-function.bcmul-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="function">{@link bcdiv()} - 两个任意精度的数字除法计算</span></li>    <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::mul()} - Multiplies an arbitrary precision number</span></li>   </ul>   </div></div>
