        #[PhpStormStubsElementAvailable(from: '7.3')] #[LanguageLevelTypeAware(['8.0' => 'int|null'], default: 'int')] $scale = null
    ) {}

    /**
 * <div id="function.bccomp" class="refentry"> <div class="refnamediv">  <h1 class="refname">bccomp</h1>  <p class="verinfo">(PHP 4, PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">bccomp</span> — <span class="dc-title">比较两个任意精度的数字</span></p> </div>  <div class="refsect1 description" id="refsect1-function.bccomp-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bccomp</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num1</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num2</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">   将 <span class="parameter" style="color:#3A95FF">num1</span> 与 <span class="parameter" style="color:#3A95FF">num2</span> 进行比较，并返回整型数字的比较结果。  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bccomp-parameters">  <h3 class="title">参数</h3><p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">num1</span></dt>     <dd>      <p class="para">       左操作数，字符串类型。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">num2</span></dt>     <dd>      <p class="para">       右操作数，字符串类型。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>     <dd>      <span class="simpara">       此参数用于设置结果小数点后的位数。       如果为 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>，则默认为使用 <span class="function">{@link bcscale()}</span> 设置的默认精度，       或者回退到 <a href="https://php.net/manual/zh/bc.configuration.php#ini.bcmath.scale" class="link"><span class="literal">bcmath.scale</span></a> INI 指令的值。      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.bccomp-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   如果所有的操作数相等返回 <span class="literal">0</span>；如果 <span class="parameter" style="color:#3A95FF">num1</span> 大于   <span class="parameter" style="color:#3A95FF">num2</span> 时返回 <span class="literal">1</span>，否则返回 <span class="literal">-1</span>。  </p> </div> <div class="refsect1 errors" id="refsect1-function.bccomp-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   此函数在下列情况下抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>：   </p><ul class="simplelist">    <li>     <span class="parameter" style="color:#3A95FF">num1</span> 或 <span class="parameter" style="color:#3A95FF">num2</span> 不是格式正确的 BCMath 数字字符串。    </li>    <li>     <span class="parameter" style="color:#3A95FF">scale</span> 超出有效范围。    </li>   </ul>   </div> <div class="refsect1 changelog" id="refsect1-function.bccomp-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       现在 <span class="parameter" style="color:#3A95FF">scale</span> 可以为 null。      </td>     </tr>    </tbody>     </table> </div>  <div class="refsect1 examples" id="refsect1-function.bccomp-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">bccomp()</strong></span> 示例</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">echo </span><span style="color: #9876AA">bccomp</span><span style="color: #007700">(</span><span style="color: #DD0000">'1'</span><span style="color: #007700">, </span><span style="color: #DD0000">'2'</span><span style="color: #007700">) . </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;   </span><span style="color: #FF8000">// -1<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">bccomp</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.00001'</span><span style="color: #007700">, </span><span style="color: #DD0000">'1'</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">); </span><span style="color: #FF8000">// 0<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">bccomp</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.00001'</span><span style="color: #007700">, </span><span style="color: #DD0000">'1'</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">); </span><span style="color: #FF8000">// 1<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-function.bccomp-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::compare()} - Compares two arbitrary precision numbers</span></li>  </ul> </div></div>
 * 
     * Compare two arbitrary precision numbers
     * @link https://php.net/manual/zh/function.bccomp.php
     * @param string $num1 <p>
     * The left operand, as a string.
     * </p>
     * @param string $num2 <p>
     * The right operand, as a string.
     * </p>
     * @param int|null $scale <p>
     * The optional <i>scale</i> parameter is used to set the
     * number of digits after the decimal place which will be used in the
     * comparison.
     * </p>
     * @return int 0 if the two operands are equal, 1 if the
     * <i>left_operand</i> is larger than the
     * <i>right_operand</i>, -1 otherwise.
     */
    #[Pure]
    function bccomp(string $num1, string $num2, ?int $scale = null): int {}

    /**
 * <div id="function.bcpowmod" class="refentry"> <div class="refnamediv">  <h1 class="refname">bcpowmod</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">bcpowmod</span> — <span class="dc-title">Raise an arbitrary precision number to another, reduced by a specified modulus</span></p> </div>  <div class="refsect1 description" id="refsect1-function.bcpowmod-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bcpowmod</strong></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$exponent</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$modulus</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="para rdfs-comment">   Use the fast-exponentiation method to raise    <span class="parameter" style="color:#3A95FF">num</span> to the power   <span class="parameter" style="color:#3A95FF">exponent</span> with respect to the modulus   <span class="parameter" style="color:#3A95FF">modulus</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bcpowmod-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">num</span></dt>     <dd>      <p class="para">       The base, as an integral string (i.e. the scale has to be zero).      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">exponent</span></dt>     <dd>      <p class="para">       The exponent, as an non-negative, integral string (i.e. the scale has to be zero).      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">modulus</span></dt>     <dd>      <p class="para">       The modulus, as an integral string (i.e. the scale has to be zero).      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>     <dd>      <span class="simpara">       此参数用于设置结果小数点后的位数。       如果为 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>，则默认为使用 <span class="function">{@link bcscale()}</span> 设置的默认精度，       或者回退到 <a href="https://php.net/manual/zh/bc.configuration.php#ini.bcmath.scale" class="link"><span class="literal">bcmath.scale</span></a> INI 指令的值。      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.bcpowmod-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns the result as a string.  </p> </div> <div class="refsect1 errors" id="refsect1-function.bcpowmod-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This function throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span>, <span class="parameter" style="color:#3A95FF">exponent</span> or <span class="parameter" style="color:#3A95FF">modulus</span> is not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">num</span>, <span class="parameter" style="color:#3A95FF">exponent</span> or <span class="parameter" style="color:#3A95FF">modulus</span> has a fractional part</li>    <li><span class="parameter" style="color:#3A95FF">exponent</span> is a negative value</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>    <p class="simpara">   This function throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception if <span class="parameter" style="color:#3A95FF">modulus</span>   is <span class="literal">0</span>.  </p> </div> <div class="refsect1 changelog" id="refsect1-function.bcpowmod-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       <span class="parameter" style="color:#3A95FF">scale</span> is now nullable.      </td>     </tr>     <tr>      <td>8.0.0</td>      <td>       Now throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> instead of returning <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> if <span class="parameter" style="color:#3A95FF">exponent</span> is a negative value.      </td>     </tr>     <tr>      <td>8.0.0</td>      <td>       Dividing by <span class="literal">0</span> now throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception instead of returning <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-function.bcpowmod-examples">  <h3 class="title">示例</h3>  <p class="para">   The following two statements are functionally identical.  The   <span class="function"><strong style="color:#CC7832">bcpowmod()</strong></span> version however, executes in   less time and can accept larger parameters.   </p><div class="informalexample">    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= </span><span style="color: #9876AA">bcpowmod</span><span style="color: #007700">(</span><span style="color: #9876AA">\$x</span><span style="color: #007700">, </span><span style="color: #9876AA">\$y</span><span style="color: #007700">, </span><span style="color: #9876AA">\$mod</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= </span><span style="color: #9876AA">bcmod</span><span style="color: #007700">(</span><span style="color: #9876AA">bcpow</span><span style="color: #007700">(</span><span style="color: #9876AA">\$x</span><span style="color: #007700">, </span><span style="color: #9876AA">\$y</span><span style="color: #007700">), </span><span style="color: #9876AA">\$mod</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// \$a and \$b are equal to each other.<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 notes" id="refsect1-function.bcpowmod-notes">  <h3 class="title">注释</h3>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    Because this method uses the modulus operation, numbers which are not    positive integers may give unexpected results.   </p>  </blockquote> </div> <div class="refsect1 seealso" id="refsect1-function.bcpowmod-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="function">{@link bcpow()} - 任意精度数字的乘方</span></li>    <li><span class="function">{@link bcmod()} - 任意精度数字取模</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::powmod()} - Raises an arbitrary precision number, reduced by a specified modulus</span></li>   </ul>   </div></div>
 * 
     * Raise an arbitrary precision number to another, reduced by a specified modulus
     * @link https://php.net/manual/zh/function.bcpowmod.php
     * @param string $num <p>
     * The base, as an integral string (i.e. the scale has to be zero).
     * </p>
     * @param string $exponent <p>
     * The exponent, as an non-negative, integral string (i.e. the scale has to be
     * zero).
     * </p>
     * @param string $modulus <p>
     * The modulus, as an integral string (i.e. the scale has to be zero).
     * </p>
     * @param int|null $scale <p>
     * This optional parameter is used to set the number of digits after the
     * decimal place in the result. If omitted, it will default to the scale
     * set globally with the {@link bcscale()} function, or fallback to 0 if
     * this has not been set.
     * </p>
     * @return string|null the result as a string, or <b>NULL</b> if <i>modulus</i>
     * is 0 or <i>exponent</i> is negative.
     */
    #[Pure]
    #[LanguageLevelTypeAware(["8.0" => "string"], default: "string|null")]
    function bcpowmod(string $num, string $exponent, string $modulus, ?int $scale = null) {}

    /**
 * <div id="function.bcfloor" class="refentry"> <div class="refnamediv">  <h1 class="refname">bcfloor</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">bcfloor</span> — <span class="dc-title">Round down arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-function.bcfloor-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bcfloor</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the next lowest integer value by rounding down   <span class="parameter" style="color:#3A95FF">num</span> if necessary.  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bcfloor-parameters">  <h3 class="title">参数</h3><dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The value to round.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-function.bcfloor-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a numeric string representing <span class="parameter" style="color:#3A95FF">num</span> rounded down to the nearest integer.  </p> </div> <div class="refsect1 errors" id="refsect1-function.bcfloor-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   This function throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if   <span class="parameter" style="color:#3A95FF">num</span> is not a well-formed BCMath numeric string.  </p> </div> <div class="refsect1 examples" id="refsect1-function.bcfloor-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">bcfloor()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcfloor</span><span style="color: #007700">(</span><span style="color: #DD0000">'4.3'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcfloor</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.999'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcfloor</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.14'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"4"<br>string(1)&nbsp;"9"<br>string(2)&nbsp;"-4"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-function.bcfloor-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcceil()} - Round up arbitrary precision number</span></li>   <li><span class="function">{@link bcround()} - Round arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::floor()} - Rounds down an arbitrary precision number</span></li>  </ul> </div></div>
 * 
     * @since 8.4
     */
    function bcfloor(string $num): string {}

    /**
 * <div id="function.bcceil" class="refentry"> <div class="refnamediv">  <h1 class="refname">bcceil</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">bcceil</span> — <span class="dc-title">Round up arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-function.bcceil-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bcceil</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the next highest integer value by rounding up   <span class="parameter" style="color:#3A95FF">num</span> if necessary.  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bcceil-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The value to round.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-function.bcceil-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a numeric string representing <span class="parameter" style="color:#3A95FF">num</span> rounded up to the nearest integer.  </p> </div> <div class="refsect1 errors" id="refsect1-function.bcceil-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   This function throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if   <span class="parameter" style="color:#3A95FF">num</span> is not a well-formed BCMath numeric string.  </p> </div> <div class="refsect1 examples" id="refsect1-function.bcceil-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">bcceil()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcceil</span><span style="color: #007700">(</span><span style="color: #DD0000">'4.3'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcceil</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.999'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcceil</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.14'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"5"<br>string(2)&nbsp;"10"<br>string(2)&nbsp;"-3"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-function.bcceil-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcfloor()} - Round down arbitrary precision number</span></li>   <li><span class="function">{@link bcround()} - Round arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::ceil()} - Rounds up an arbitrary precision number</span></li>  </ul> </div></div>
 * 
     * @since 8.4
     */
    function bcceil(string $num): string {}

    /**
 * <div id="function.bcround" class="refentry"> <div class="refnamediv">  <h1 class="refname">bcround</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">bcround</span> — <span class="dc-title">Round arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-function.bcround-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bcround</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$precision</span><span class="initializer"> = 0</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.roundingmode.php" class="type RoundingMode" style="color:#EAB766">RoundingMode</a></span> <span class="parameter" style="color:#3A95FF">\$mode</span><span class="initializer"> = <strong><span>RoundingMode::HalfAwayFromZero</span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the rounded value of <span class="parameter" style="color:#3A95FF">num</span> to   specified <span class="parameter" style="color:#3A95FF">precision</span>   (number of digits after the decimal point).   <span class="parameter" style="color:#3A95FF">precision</span> can also be negative or zero (default).  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bcround-parameters">  <h3 class="title">参数</h3>  <dl>        <dt><span class="parameter" style="color:#3A95FF">num</span></dt>     <dd>      <p class="para">       要处理的值。      </p>     </dd>            <dt><span class="parameter" style="color:#3A95FF">precision</span></dt>     <dd>      <p class="para">       可选的十进制小数点后数字的数目。      </p>      <p class="para">       如果 <span class="parameter" style="color:#3A95FF">precision</span> 是正数，则 <span class="parameter" style="color:#3A95FF">num</span>       会四舍五入到小数点后 <span class="parameter" style="color:#3A95FF">precision</span> 位有效数字。      </p>      <p class="para">       如果 <span class="parameter" style="color:#3A95FF">precision</span> 是负数，则 <span class="parameter" style="color:#3A95FF">num</span>       四舍五入到小数点前 <span class="parameter" style="color:#3A95FF">precision</span> 位有效数字。即 <span class="code">pow(10,       -\$precision)</span> 最接近的倍数，例如，<span class="parameter" style="color:#3A95FF">precision</span>       为 -1，<span class="parameter" style="color:#3A95FF">num</span> 可以四舍五入到十位，<span class="parameter" style="color:#3A95FF">precision</span>       为 -2，<span class="parameter" style="color:#3A95FF">num</span> 可以四舍五入到百位，等等。      </p>     </dd>           <dt id="bcmath-number.round..parameters.mode"><span class="parameter" style="color:#3A95FF">mode</span></dt>    <dd>     <span class="simpara">      Specifies the rounding mode. For more information about modes, see <span class="enumname"><a href="https://php.net/manual/zh/enum.roundingmode.php" class="enumname">RoundingMode</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-function.bcround-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a numeric string representing <span class="parameter" style="color:#3A95FF">num</span> rounded to the given precision.  </p> </div> <div class="refsect1 errors" id="refsect1-function.bcround-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This function throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is not a well-formed BCMath numeric string.</li>    <li>An invalid <span class="parameter" style="color:#3A95FF">mode</span> is specified.</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-function.bcround-examples">  <h3 class="title">示例</h3>   <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">bcround()</strong></span> examples</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.4'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.5'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.6'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.6'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'5.045'</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'5.055'</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'345'</span><span style="color: #007700">, -</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'345'</span><span style="color: #007700">, -</span><span style="color: #9876AA">3</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'678'</span><span style="color: #007700">, -</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'678'</span><span style="color: #007700">, -</span><span style="color: #9876AA">3</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"3"<br>string(1)&nbsp;"4"<br>string(1)&nbsp;"4"<br>string(1)&nbsp;"4"<br>string(4)&nbsp;"5.05"<br>string(4)&nbsp;"5.06"<br>string(3)&nbsp;"300"<br>string(1)&nbsp;"0"<br>string(3)&nbsp;"700"<br>string(4)&nbsp;"1000"</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2     Example of using <span class="function"><strong style="color:#CC7832">bcround()</strong></span> with different <span class="parameter" style="color:#3A95FF">precision</span> values   </strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= </span><span style="color: #DD0000">'123.45'</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, -</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, -</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, -</span><span style="color: #9876AA">3</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(7)&nbsp;"123.450"<br>string(6)&nbsp;"123.45"<br>string(5)&nbsp;"123.5"<br>string(3)&nbsp;"123"<br>string(3)&nbsp;"120"<br>string(3)&nbsp;"100"<br>string(1)&nbsp;"0"</blockquote></div>   </div>  </div>  <div class="example" id="example-3">   <p><strong>示例 #3     Example of using <span class="function"><strong style="color:#CC7832">bcround()</strong></span> with different <span class="parameter" style="color:#3A95FF">mode</span> values   </strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">echo </span><span style="color: #DD0000">'Rounding modes with 9.5' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfAwayFromZero</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfTowardsZero</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfEven</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfOdd</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">TowardsZero</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">AwayFromZero</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">NegativeInfinity</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">PositiveInfinity</span><span style="color: #007700">));<br><br>echo </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>echo </span><span style="color: #DD0000">'Rounding modes with 8.5' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfAwayFromZero</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.5'</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfTowardsZero</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">bcround</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.5'</span><span style="color: #007700