"refsect1 seealso" id="refsect1-function.bcround-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcceil()} - Round up arbitrary precision number</span></li>   <li><span class="function">{@link bcfloor()} - Round down arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::round()} - Rounds an arbitrary precision number</span></li>  </ul> </div></div>
 * 
     * @since 8.4
     */
    function bcround(string $num, int $precision = 0, RoundingMode $mode = RoundingMode::HalfAwayFromZero): string {}

    /**
 * <div id="function.bcdivmod" class="refentry"> <div class="refnamediv">  <h1 class="refname">bcdivmod</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">bcdivmod</span> — <span class="dc-title">Get the quotient and modulus of an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-function.bcdivmod-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>bcdivmod</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num1</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$num2</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Get the quotient and remainder of dividing <span class="parameter" style="color:#3A95FF">num1</span> by   <span class="parameter" style="color:#3A95FF">num2</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-function.bcdivmod-parameters">  <h3 class="title">参数</h3><p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">num1</span></dt>     <dd>      <p class="para">       被除数，字符串类型。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">num2</span></dt>     <dd>      <p class="para">       除数，字符串类型。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>     <dd>      <span class="simpara">       此参数用于设置结果小数点后的位数。       如果为 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>，则默认为使用 <span class="function">{@link bcscale()}</span> 设置的默认精度，       或者回退到 <a href="https://php.net/manual/zh/bc.configuration.php#ini.bcmath.scale" class="link"><span class="literal">bcmath.scale</span></a> INI 指令的值。      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.bcdivmod-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an indexed <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> where the first element is the quotient as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>   and the second element is the remainder as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 errors" id="refsect1-function.bcdivmod-errors">    <h3 class="title">错误／异常</h3><p class="para">   此函数在下列情况下抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span>：   </p><ul class="simplelist">    <li>     <span class="parameter" style="color:#3A95FF">num1</span> 或 <span class="parameter" style="color:#3A95FF">num2</span> 不是格式正确的 BCMath 数字字符串。    </li>    <li>     <span class="parameter" style="color:#3A95FF">scale</span> 超出有效范围。    </li>   </ul>    <p class="simpara">   如果 <span class="parameter" style="color:#3A95FF">num2</span> 为 <span class="literal">0</span>，此函数会抛出 <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> 异常。  </p> </div> <div class="refsect1 examples" id="refsect1-function.bcdivmod-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">bcdivmod()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>bcscale</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">);<br><br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = </span><span style="color: #9876AA">bcdivmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'5'</span><span style="color: #007700">,  </span><span style="color: #DD0000">'3'</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$quot</span><span style="color: #007700">; </span><span style="color: #FF8000">// 1<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">;  </span><span style="color: #FF8000">// 2<br><br></span><span style="color: #007700">[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = </span><span style="color: #9876AA">bcdivmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'5'</span><span style="color: #007700">,  </span><span style="color: #DD0000">'-3'</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$quot</span><span style="color: #007700">; </span><span style="color: #FF8000">// -1<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">;  </span><span style="color: #FF8000">// 2<br><br></span><span style="color: #007700">[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = </span><span style="color: #9876AA">bcdivmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'-5'</span><span style="color: #007700">,  </span><span style="color: #DD0000">'3'</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$quot</span><span style="color: #007700">; </span><span style="color: #FF8000">// -1<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">;  </span><span style="color: #FF8000">// -2<br><br></span><span style="color: #007700">[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = </span><span style="color: #9876AA">bcdivmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'-5'</span><span style="color: #007700">,  </span><span style="color: #DD0000">'-3'</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$quot</span><span style="color: #007700">; </span><span style="color: #FF8000">// 1<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">;  </span><span style="color: #FF8000">// -2<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">bcdivmod()</strong></span> with decimals</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = </span><span style="color: #9876AA">bcdivmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'5.7'</span><span style="color: #007700">, </span><span style="color: #DD0000">'1.3'</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$quot</span><span style="color: #007700">; </span><span style="color: #FF8000">// 4<br></span><span style="color: #007700">echo </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">;  </span><span style="color: #FF8000">// 0.5<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-function.bcdivmod-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcdiv()} - 两个任意精度的数字除法计算</span></li>   <li><span class="function">{@link bcmod()} - 任意精度数字取模</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::divmod()} - Gets the quotient and modulus of an arbitrary precision number</span></li>  </ul> </div></div>
 * 
     * @return string[]
     */
    function bcdivmod(string $num1, string $num2, ?int $scale = null): array {}
}

namespace BcMath {
    /**
 * <div id="class.bcmath-number" class="reference"> <h1 class="title">The BcMath\Number class</h1>  <div class="partintro"><p class="verinfo">(PHP 8 &gt;= 8.4.0)</p>  <div class="section" id="bcmath-number.intro">   <h2 class="title">简介</h2>   <p class="simpara">    A class for an arbitrary precision number.    These objects support overloaded    <a href="https://php.net/manual/zh/language.operators.arithmetic.php" class="link">arithmetic</a> and    <a href="https://php.net/manual/zh/language.operators.comparison.php" class="link">comparison</a> operators.   </p>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     This class is not affected by the     <a href="https://php.net/manual/zh/bc.configuration.php#ini.bcmath.scale" class="link">bcmath.scale</a>     INI directive set in <var class="filename">php.ini</var>.    </span>   </p></blockquote>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">     The behavior of an overloaded operator is the same as specifying <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> for the     <span class="parameter" style="color:#3A95FF">scale</span> parameter on the corresponding method.    </span>   </p></blockquote>  </div>  <div class="section" id="bcmath-number.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">    <span class="modifier">namespace</span> <strong class="package">BcMath</strong>;</div>    <div class="classsynopsisinfo">           <span class="modifier">final</span>      <span class="modifier">readonly</span>      <span class="modifier">class</span> <strong class="classname"><strong class="classname">Number</strong></strong>                <span class="modifier">implements</span>       <a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a> {</div>     <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>     <div class="fieldsynopsis">      <span class="modifier">public</span>      <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>       <var class="varname"><a href="https://php.net/manual/zh/class.bcmath-number.php#bcmath-number.props.value">\$<var class="varname">value</var></a></var>;</div>     <div class="fieldsynopsis"><span class="modifier">public</span>      <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>       <var class="varname"><a href="https://php.net/manual/zh/class.bcmath-number.php#bcmath-number.props.scale">\$<var class="varname">scale</var></a></var>;</div>     <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>     <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>)</div>     <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.add.php" class="methodname" style="color:#CC7832">add</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.ceil.php" class="methodname" style="color:#CC7832">ceil</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.compare.php" class="methodname" style="color:#CC7832">compare</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.div.php" class="methodname" style="color:#CC7832">div</a></span>(<span class="methodparam"><span class="type" style="color: