766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.tostring.php" class="methodname" style="color:#CC7832">__toString</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/bcmath-number.unserialize.php" class="methodname" style="color:#CC7832">__unserialize</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>    }   </div>  </div>  <div class="section" id="bcmath-number.props">   <h2 class="title">属性</h2>   <dl>         <dt id="bcmath-number.props.value"><var class="varname">value</var></dt>     <dd>      <span class="simpara">       A string representation of an arbitrary precision number.      </span>     </dd>             <dt id="bcmath-number.props.scale"><var class="varname">scale</var></dt>     <dd>      <span class="simpara">       The scale value currently set on the object.       For objects resulting from calculations, this value is automatically computed and set,       unless the <span class="parameter" style="color:#3A95FF">scale</span> parameter was set in the calculation method.      </span>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link BcMath\Number::add} — Adds an arbitrary precision number</li><li>{@link BcMath\Number::ceil} — Rounds up an arbitrary precision number</li><li>{@link BcMath\Number::compare} — Compares two arbitrary precision numbers</li><li>{@link BcMath\Number::__construct} — Creates a BcMath\Number object</li><li>{@link BcMath\Number::div} — Divides by an arbitrary precision number</li><li>{@link BcMath\Number::divmod} — Gets the quotient and modulus of an arbitrary precision number</li><li>{@link BcMath\Number::floor} — Rounds down an arbitrary precision number</li><li>{@link BcMath\Number::mod} — Gets the modulus of an arbitrary precision number</li><li>{@link BcMath\Number::mul} — Multiplies an arbitrary precision number</li><li>{@link BcMath\Number::pow} — Raises an arbitrary precision number</li><li>{@link BcMath\Number::powmod} — Raises an arbitrary precision number, reduced by a specified modulus</li><li>{@link BcMath\Number::round} — Rounds an arbitrary precision number</li><li>{@link BcMath\Number::__serialize} — Serializes a BcMath\Number object</li><li>{@link BcMath\Number::sqrt} — Gets the square root of an arbitrary precision number</li><li>{@link BcMath\Number::sub} — Subtracts an arbitrary precision number</li><li>{@link BcMath\Number::__toString} — Converts BcMath\Number to string</li><li>{@link BcMath\Number::__unserialize} — Deserializes a data parameter into a BcMath\Number object</li></ul></div>
 * 
     * @since 8.4
     */
    final readonly class Number implements \Stringable
    {
        /** @var numeric-string */
        public readonly string $value;
        public readonly int $scale;

        /**
 * <div id="bcmath-number.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::__construct</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::__construct</span> — <span class="dc-title">Creates a BcMath\Number object</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>)</div>  <p class="simpara">   Creates a <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object from an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> or <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> value.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> or <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> value.      If <span class="parameter" style="color:#3A95FF">num</span> is a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>,      the <span class="property">{@link BcMath\Number::scale}</span> is always set to <span class="literal">0</span>.      If <span class="parameter" style="color:#3A95FF">num</span> is a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, it must be a valid number,      and the <span class="property">{@link BcMath\Number::scale}</span> is automatically set by parsing the string.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.construct-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if <span class="parameter" style="color:#3A95FF">num</span>   is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$num1 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #9876AA">100</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$num2 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-200'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$num3 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'300.00'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$num1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$num2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$num3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"100"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-200"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"300.00"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::__serialize()} - Serializes a BcMath\Number object</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::__unserialize()} - Deserializes a data parameter into a BcMath\Number object</span></li>  </ul> </div></div>
 * 
         * @param int|numeric-string $num
         * @throws \ValueError
         */
        public function __construct(string|int $num) {}

        /**
 * <div id="bcmath-number.add" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::add</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::add</span> — <span class="dc-title">Adds an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.add-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::add</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Adds <var class="varname">\$this</var> and <span class="parameter" style="color:#3A95FF">num</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.add-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The value to add.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.add-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result of addition as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the greater <span class="property">{@link BcMath\Number::scale}</span> of the two numbers used for addition is used.  </p>  <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span>s of two values are <span class="literal">2</span>   and <span class="literal">5</span> respectively, the <span class="property">{@link BcMath\Number::scale}</span> of the result   will be <span class="literal">5</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.add-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-bcmath-number.add-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::add()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.34567'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.456'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">7</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"3.57967"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(5)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"-2.222"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"8.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::add()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.34567'</span><span style="color: #007700">), </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.456'</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">7</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"3.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(13)&nbsp;"-2.2220000000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(10)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"8"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.add-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcadd()} - 两个任意精度数字的加法计算</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::sub()} - Subtracts an arbitrary precision number</span></li>  </ul> </div></div>
