        /**
 * <div id="bcmath-number.sub" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::sub</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::sub</span> — <span class="dc-title">Subtracts an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.sub-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::sub</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Subtracts <span class="parameter" style="color:#3A95FF">num</span> from <var class="varname">\$this</var>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.sub-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The value to subtract.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.sub-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result of subtraction as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the greater <span class="property">{@link BcMath\Number::scale}</span> of the two numbers used for subtraction is used.  </p>    <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span>s of two values are <span class="literal">2</span>   and <span class="literal">5</span> respectively, the <span class="property">{@link BcMath\Number::scale}</span> of the result   will be <span class="literal">5</span>.  </p> </div>  <div class="refsect1 errors" id="refsect1-bcmath-number.sub-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-bcmath-number.sub-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::sub()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sub</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.34567'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sub</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.456'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sub</span><span style="color: #007700">(</span><span style="color: #9876AA">7</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"-1.11167"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(5)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"4.690"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"-5.766"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::sub()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sub</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.34567'</span><span style="color: #007700">), </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sub</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.456'</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sub</span><span style="color: #007700">(</span><span style="color: #9876AA">7</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-1.1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(12)&nbsp;"4.6900000000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(10)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.sub-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcsub()} - 两个任意精度数字的减法</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::add()} - Adds an arbitrary precision number</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $num
         * @throws \ValueError
         */
        public function sub(Number|string|int $num, ?int $scale = null): Number {}

        /**
 * <div id="bcmath-number.mul" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::mul</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::mul</span> — <span class="dc-title">Multiplies an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.mul-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::mul</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Multiplies <var class="varname">\$this</var> by <span class="parameter" style="color:#3A95FF">num</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.mul-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The multiplier.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.mul-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result of multiplication as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the sum of the <span class="property">{@link BcMath\Number::scale}</span>s of the two values used for multiplication is used.  </p>  <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span>s of two values are <span class="literal">2</span>   and <span class="literal">5</span> respectively, the <span class="property">{@link BcMath\Number::scale}</span> of the result   will be <span class="literal">7</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.mul-errors">  <h3 class="title">错误／异常</h3>    <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>    <li><span class="property">{@link BcMath\Number::scale}</span> of the result object is outside the valid range</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-bcmath-number.mul-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::mul()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mul</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.3456'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mul</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.4'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mul</span><span style="color: #007700">(</span><span style="color: #9876AA">7</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(9)&nbsp;"2.8944704"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(7)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"-4.1956"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(4)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"8.638"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::mul()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mul</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.3456'</span><span style="color: #007700">), </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mul</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.4'</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mul</span><span style="color: #007700">(</span><span style="color: #9876AA">7</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.234"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"2.8"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(13)&nbsp;"-4.1956000000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(10)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"8"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.mul-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcmul()} - 两个任意精度数字乘法计算</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()} - Divides by an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::pow()} - Raises an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::powmod()} - Raises an arbitrary precision number, reduced by a specified modulus</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $num
         * @throws \ValueError
         */
        public function mul(Number|string|int $num, ?int $scale = null): Number {}

        /**
 * <div id="bcmath-number.div" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::div</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::div</span> — <span class="dc-title">Divides by an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.div-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::div</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Divides <var class="varname">\$this</var> by <span class="parameter" style="color:#3A95FF">num</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.div-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The divisor.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.div-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result of division as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the <span class="property">{@link BcMath\Number::scale}</span> of the dividend is used. However, in cases such   as indivisible division, the <span class="property">{@link BcMath\Number::scale}</span> of the result is expanded.   Expansion is done only as needed, up to a maximum of <span class="literal">+10</span>.  </p>  <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span> of the dividend is <span class="literal">5</span>,   the <span class="property">{@link BcMath\Number::scale}</span> of the result is between <span class="literal">5</span> and   <span class="literal">15</span>.  </p>  <p class="simpara">   Even in indivisible calculations, the <span class="property">{@link BcMath\Number::scale}</span> will not always be   <span class="literal">+10</span>.   A <span class="literal">0</span> at the end of the result is considered not to need expansion, so the   <span class="property">{@link BcMath\Number::scale}</span> is reduced by that amount.   The <span class="property">{@link BcMath\Number::scale}</span> will never be less than the   <span class="property">{@link BcMath\Number::scale}</span> before expansion.   See also the <a href="https://php.net/manual/zh/bcmath-number.div.php#bcmath-number.div.example.expansion-scale" class="link">code example</a>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.div-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>    <li><span class="property">{@link BcMath\Number::scale}</span> of the result object is outside the valid range</li>   </ul>    <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception if   <span class="parameter" style="color:#3A95FF">num</span> is <span class="literal">0</span>.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.div-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::div()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'0.002'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.000'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #9876AA">32</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"0.002"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"0.001"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(16)&nbsp;"-0.0006666666666"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(13)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(9)&nbsp;"0.0000625"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(7)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::div()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'0.002'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.000'</span><span style="color: #007700">), </span><span style="color: #9876AA">15</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3'</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #9876AA">32</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"0.002"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(17)&nbsp;"0.001000000000000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(15)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"-0.00066"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(5)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"0.00"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="bcmath-number.div.example.expansion-scale">   <p><strong>示例 #3 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::div()</strong></span> example of expansioning <span class="property">{@link BcMath\Number::scale}</span> of result object</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'0.001'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #DD0000">'10001'</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'0.001'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #DD0000">'10001'</span><span style="color: #007700">, </span><span style="color: #9876AA">13</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'0.001'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">div</span><span style="color: #007700">(</span><span style="color: #DD0000">'100000000000001'</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(13)&nbsp;"0.00000009999"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(11)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(15)&nbsp;"0.0000000999900"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(13)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"0.000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.div-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcdiv()} - 两个任意精度的数字除法计算</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::divmod()} - Gets the quotient and modulus of an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::mod()} - Gets the modulus of an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::sqrt()} - Gets the square root of an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::pow()} - Raises an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::mul()} - Multiplies an arbitrary precision number</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $num
         * @throws \DivisionByZeroError
         * @throws \ValueError
         */
        public function div(Number|string|int $num, ?int $scale = null): Number {}

        /**
 * <div id="bcmath-number.mod" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::mod</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::mod</span> — <span class="dc-title">Gets the modulus of an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.mod-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::mod</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Gets the remainder of dividing <var class="varname">\$this</var> by <span class="parameter" style="color:#3A95FF">num</span>.   Unless <span class="parameter" style="color:#3A95FF">num</span> is <span class="literal">0</span>, the result has the same sign   as <var class="varname">\$this</var>.  </p> </div>  <div class="refsect1 parameters" id="refsect1-bcmath-number.mod-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The divisor.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.mod-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the modulus as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the greater <span class="property">{@link BcMath\Number::scale}</span> of the two numbers used for modulus operation is used.  </p>    <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span>s of two values are <span class="literal">2</span>   and <span class="literal">5</span> respectively, the <span class="property">{@link BcMath\Number::scale}</span> of the result   will be <span class="literal">5</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.mod-errors">  <h3 class="title">错误／异常</h3>    <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>      <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception if   <span class="parameter" style="color:#3A95FF">num</span> is <span class="literal">0</span>.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.mod-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::mod()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.22'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mod</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mod</span><span style="color: #007700">(-</span><span style="color: #9876AA">5</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"8.3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"1.64"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"0.0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"3.3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::mod()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.22'</span><span style="color: #007700">), </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mod</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">mod</span><span style="color: #007700">(-</span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"8.3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"1.6"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"0.000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.mod-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcmod()} - 任意精度数字取模</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()} - Divides by an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::divmod()} - Gets the quotient and modulus of an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::powmod()} - Raises an arbitrary precision number, reduced by a specified modulus</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $num
