         */
        public function mod(Number|string|int $num, ?int $scale = null): Number {}

        /**
 * <div id="bcmath-number.divmod" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::divmod</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::divmod</span> — <span class="dc-title">Gets the quotient and modulus of an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.divmod-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::divmod</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Gets the quotient and remainder of dividing <var class="varname">\$this</var> by <span class="parameter" style="color:#3A95FF">num</span>.  </p> </div>  <div class="refsect1 parameters" id="refsect1-bcmath-number.divmod-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The divisor.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.divmod-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an indexed <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> where the first element is the quotient as a new   <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object and the second element is the remainder as a new   <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   The quotient is always an integer value, so <span class="property">{@link BcMath\Number::scale}</span> of the quotient will   always be <span class="literal">0</span>, regardless of whether explicitly specify <span class="parameter" style="color:#3A95FF">scale</span>.  </p>  <p class="simpara">   If <span class="parameter" style="color:#3A95FF">scale</span> is explicitly specified, <span class="property">{@link BcMath\Number::scale}</span> of the   remainder will be the specified value.   When the <span class="property">{@link BcMath\Number::scale}</span> of the result's remainder object is automatically set,   the greater <span class="property">{@link BcMath\Number::scale}</span> of the two numbers used for modulus operation is used.  </p>  <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span>s of two values are <span class="literal">2</span>   and <span class="literal">5</span> respectively, the <span class="property">{@link BcMath\Number::scale}</span> of the remainder   will be <span class="literal">5</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.divmod-errors">  <h3 class="title">错误／异常</h3>    <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>      <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception if   <span class="parameter" style="color:#3A95FF">num</span> is <span class="literal">0</span>.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.divmod-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::divmod()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">echo </span><span style="color: #DD0000">'8.3 / 2.22' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">divmod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.22'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">PHP_EOL </span><span style="color: #007700">. </span><span style="color: #DD0000">'8.3 / 8.3' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">divmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">PHP_EOL </span><span style="color: #007700">. </span><span style="color: #DD0000">'10 / -3' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'10'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">divmod</span><span style="color: #007700">(-</span><span style="color: #9876AA">3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">8.3&nbsp;/&nbsp;2.22<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"1.34"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br><br>8.3&nbsp;/&nbsp;8.3<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"0.0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br><br>10&nbsp;/&nbsp;-3<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::divmod()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">echo </span><span style="color: #DD0000">'8.3 / 2.22' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">divmod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2.22'</span><span style="color: #007700">), </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">PHP_EOL </span><span style="color: #007700">. </span><span style="color: #DD0000">'8.3 / 8.3' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">divmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.3'</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">);<br><br>echo </span><span style="color: #9876AA">PHP_EOL </span><span style="color: #007700">. </span><span style="color: #DD0000">'10 / -3' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>[</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">] = new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'10'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">divmod</span><span style="color: #007700">(-</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$quot</span><span style="color: #007700">, </span><span style="color: #9876AA">\$rem</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">8.3&nbsp;/&nbsp;2.22<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"1.3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br><br>8.3&nbsp;/&nbsp;8.3<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"0.0000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(4)<br>}<br><br>10&nbsp;/&nbsp;-3<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"1.00000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(5)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.divmod-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcdivmod()} - Get the quotient and modulus of an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()} - Divides by an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::mod()} - Gets the modulus of an arbitrary precision number</span></li>  </ul> </div></div>
