         * @throws \ValueError
         */
        public function divmod(Number|string|int $num, ?int $scale = null): array {}

        /**
 * <div id="bcmath-number.powmod" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::powmod</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::powmod</span> — <span class="dc-title">Raises an arbitrary precision number, reduced by a specified modulus</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.powmod-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::powmod</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$exponent</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$modulus</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Use the fast-exponentiation method to raise <var class="varname">\$this</var> to the power   <span class="parameter" style="color:#3A95FF">exponent</span> with respect to the modulus <span class="parameter" style="color:#3A95FF">modulus</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.powmod-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">exponent</span></dt>    <dd>     <span class="simpara">       The exponent, as an non-negative and integral (i.e. the scale has to be zero).     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">modulus</span></dt>    <dd>     <span class="simpara">       The modulus, as an integral (i.e. the scale has to be zero).     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.powmod-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the <span class="property">{@link BcMath\Number::scale}</span> of the result object will always be <span class="literal">0</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.powmod-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">exponent</span> or <span class="parameter" style="color:#3A95FF">modulus</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not    a well-formed BCMath numeric string</li>    <li><var class="varname">\$this</var>, <span class="parameter" style="color:#3A95FF">exponent</span> or <span class="parameter" style="color:#3A95FF">modulus</span> has a fractional part</li>    <li><span class="parameter" style="color:#3A95FF">exponent</span> is a negative value</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>    <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception if <span class="parameter" style="color:#3A95FF">modulus</span>   is <span class="literal">0</span>.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.powmod-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::powmod()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3'</span><span style="color: #007700">), </span><span style="color: #9876AA">5</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3'</span><span style="color: #007700">), </span><span style="color: #9876AA">5</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'2'</span><span style="color: #007700">, -</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(</span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">7</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"2"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-2"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::powmod()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3'</span><span style="color: #007700">), </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3'</span><span style="color: #007700">), </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(</span><span style="color: #DD0000">'2'</span><span style="color: #007700">, -</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-8'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">powmod</span><span style="color: #007700">(</span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">7</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"2.0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"-2.00"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"-1.0000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(4)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.powmod-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcpowmod()} - Raise an arbitrary precision number to another, reduced by a specified modulus</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::pow()} - Raises an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::mod()} - Gets the modulus of an arbitrary precision number</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $exponent
         * @param Number|int|numeric-string $modulus
         * @throws \DivisionByZeroError
         * @throws \ValueError
         */
        public function powmod(Number|string|int $exponent, Number|string|int $modulus, ?int $scale = null): Number {}

        /**
 * <div id="bcmath-number.pow" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::pow</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::pow</span> — <span class="dc-title">Raises an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.pow-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::pow</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$exponent</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Raises <var class="varname">\$this</var> to the <span class="parameter" style="color:#3A95FF">exponent</span> power.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.pow-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">exponent</span></dt>    <dd>     <span class="simpara">       The exponent. Must be a value with no fractional part.       The valid range of the <span class="parameter" style="color:#3A95FF">exponent</span> is platform specific,       but it is at least <span class="literal">-2147483648</span> to <span class="literal">2147483647</span>.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.pow-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result of power as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="para">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   depending on the value of <span class="parameter" style="color:#3A95FF">exponent</span>, the <span class="property">BcMath\Number::scale   </span> of result will be as follows:   </p><table class="doctable informaltable">         <thead>      <tr>       <th><span class="parameter" style="color:#3A95FF">exponent</span></th>       <th><span class="property">{@link BcMath\Number::scale}</span> of result</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>positive</td>       <td>(<span class="property">{@link BcMath\Number::scale}</span> of power base) * (<span class="parameter" style="color:#3A95FF">exponent</span>'s value)</td>      </tr>      <tr>       <td><span class="literal">0</span></td>       <td><span class="literal">0</span></td>      </tr>      <tr>       <td>negative</td>       <td>Between (<span class="property">{@link BcMath\Number::scale}</span> of power base) and (<span class="property">BcMath\Number::scale       </span> of power base + <span class="literal">10</span>)</td>      </tr>     </tbody>       </table>    <p class="simpara">   If an indivisible division occurs due to a negative <span class="parameter" style="color:#3A95FF">exponent</span>, the <span class="property">   BcMath\Number::scale</span> of the result is expanded. Expansion is done only as needed, up to   a maximum of <span class="literal">+10</span>.   This behavior is the same as <span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()}</span>, so please see that for details.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.pow-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">exponent</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">exponent</span> has a fractional part</li>    <li><span class="parameter" style="color:#3A95FF">exponent</span> or <span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>    <li><span class="property">{@link BcMath\Number::scale}</span> of the result object is outside the valid range</li>   </ul>    <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.divisionbyzeroerror.php" class="exceptionname">DivisionByZeroError</a></span> exception if <var class="varname">\$this</var>'s value   is <span class="literal">0</span> and <span class="parameter" style="color:#3A95FF">exponent</span> is a negative value.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.pow-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::pow()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.0'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pow</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'5'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pow</span><span style="color: #007700">(</span><span style="color: #DD0000">'-1'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pow</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"3.0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(9)&nbsp;"243.00000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(5)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(13)&nbsp;"0.33333333333"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(11)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"1"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::pow()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.0'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$ret1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pow</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'5'</span><span style="color: #007700">), </span><span style="color: #9876AA">0</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pow</span><span style="color: #007700">(</span><span style="color: #DD0000">'-1'</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$ret3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pow</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$number</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$ret3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"3.0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"243"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"0.33"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(12)&nbsp;"1.0000000000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(10)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.pow-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcpow()} - 任意精度数字的乘方</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::powmod()} - Raises an arbitrary precision number, reduced by a specified modulus</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::mul()} - Multiplies an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::sqrt()} - Gets the square root of an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()} - Divides by an arbitrary precision number</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $exponent
         * @throws \DivisionByZeroError
         * @throws \ValueError
         */
        public function pow(Number|string|int $exponent, ?int $scale = null): Number {}

/**
 * <div id="bcmath-number.sqrt" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::sqrt</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::sqrt</span> — <span class="dc-title">Gets the square root of an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.sqrt-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::sqrt</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Return the square root of <var class="varname">\$this</var>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.sqrt-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>    <dd>     <span class="simpara">      <span class="property">{@link BcMath\Number::scale}</span> explicitly specified for calculation results.      If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, the <span class="property">{@link BcMath\Number::scale}</span> of the calculation result will be set automatically.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.sqrt-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the square root as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p>  <p class="simpara">   When the <span class="property">{@link BcMath\Number::scale}</span> of the result object is automatically set,   the <span class="property">{@link BcMath\Number::scale}</span> of <var class="varname">\$this</var> is used. However, in cases such   as indivisible division, the <span class="property">{@link BcMath\Number::scale}</span> of the result is expanded.   Expansion is done only as needed, up to a maximum of <span class="literal">+10</span>.   This behavior is the same as <span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()}</span>, so please see that for details.  </p>  <p class="simpara">   That is, if the <span class="property">{@link BcMath\Number::scale}</span> of <var class="varname">\$this</var> is <span class="literal">5</span>,   the <span class="property">{@link BcMath\Number::scale}</span> of the result is between <span class="literal">5</span> and   <span class="literal">15</span>.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.sqrt-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><var class="varname">\$this</var> is a negative value</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>    <li><span class="property">{@link BcMath\Number::scale}</span> of the result object is outside the valid range</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-bcmath-number.sqrt-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::sqrt()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">sqrt</span><span style="color: #007700">(),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'2'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">sqrt</span><span style="color: #007700">(</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'4'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">sqrt</span><span style="color: #007700">(),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'4'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">sqrt</span><span style="color: #007700">(</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(12)&nbsp;"1.4142135623"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(10)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"1.414"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"2"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"2.000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.sqrt-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcsqrt()} - 任意精度数字的二次方根</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::div()} - Divides by an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::pow()} - Raises an arbitrary precision number</span></li>  </ul> </div></div>
 */
        public function sqrt(?int $scale = null): Number {}

/**
 * <div id="bcmath-number.floor" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::floor</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::floor</span> — <span class="dc-title">Rounds down an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.floor-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::floor</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Returns the next highest integer value by rounding down   <var class="varname">\$this</var> if necessary.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.floor-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div>  <div class="refsect1 returnvalues" id="refsect1-bcmath-number.floor-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.   The <span class="property">{@link BcMath\Number::scale}</span> of the result is always <span class="literal">0</span>.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.floor-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::floor()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$num1 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'4.3'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">floor</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$num2 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.999'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">floor</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$num3 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.14'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">floor</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$num1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$num2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$num3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"4"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"9"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-4"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.floor-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcfloor()} - Round down arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::ceil()} - Rounds up an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::round()} - Rounds an arbitrary precision number</span></li>  </ul> </div></div>
 */
        public function floor(): Number {}

/**
 * <div id="bcmath-number.ceil" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::ceil</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::ceil</span> — <span class="dc-title">Rounds up an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.ceil-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::ceil</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Returns the next highest integer value by rounding up   <var class="varname">\$this</var> if necessary.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.ceil-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.ceil-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.   The <span class="property">{@link BcMath\Number::scale}</span> of the result is always <span class="literal">0</span>.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.ceil-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::ceil()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$num1 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'4.3'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">ceil</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$num2 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.999'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">ceil</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$num3 </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'-3.14'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">ceil</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$num1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$num2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$num3</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"10"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"-3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.ceil-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcceil()} - Round up arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::floor()} - Rounds down an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::round()} - Rounds an arbitrary precision number</span></li>  </ul> </div></div>
 */
        public function ceil(): Number {}

/**
 * <div id="bcmath-number.round" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::round</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::round</span> — <span class="dc-title">Rounds an arbitrary precision number</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.round-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::round</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$precision</span><span class="initializer"> = 0</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.roundingmode.php" class="type RoundingMode" style="color:#EAB766">RoundingMode</a></span> <span class="parameter" style="color:#3A95FF">\$mode</span><span class="initializer"> = <strong><span>RoundingMode::HalfAwayFromZero</span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span></div>  <p class="simpara">   Returns the rounded value of <var class="varname">\$this</var> to   specified <span class="parameter" style="color:#3A95FF">precision</span>   (number of digits after the decimal point).   <span class="parameter" style="color:#3A95FF">precision</span> can also be negative or zero (default).  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.round-parameters">  <h3 class="title">参数</h3>  <dl>           <dt><span class="parameter" style="color:#3A95FF">precision</span></dt>     <dd>      <p class="para">       可选的十进制小数点后数字的数目。      </p>      <p class="para">       如果 <span class="parameter" style="color:#3A95FF">precision</span> 是正数，则 <span class="parameter" style="color:#3A95FF">num</span>       会四舍五入到小数点后 <span class="parameter" style="color:#3A95FF">precision</span> 位有效数字。      </p>      <p class="para">       如果 <span class="parameter" style="color:#3A95FF">precision</span> 是负数，则 <span class="parameter" style="color:#3A95FF">num</span>       四舍五入到小数点前 <span class="parameter" style="color:#3A95FF">precision</span> 位有效数字。即 <span class="code">pow(10,       -\$precision)</span> 最接近的倍数，例如，<span class="parameter" style="color:#3A95FF">precision</span>       为 -1，<span class="parameter" style="color:#3A95FF">num</span> 可以四舍五入到十位，<span class="parameter" style="color:#3A95FF">precision</span>       为 -2，<span class="parameter" style="color:#3A95FF">num</span> 可以四舍五入到百位，等等。      </p>     </dd>           <dt><span class="parameter" style="color:#3A95FF">mode</span></dt>    <dd>     <span class="simpara">      Specifies the rounding mode. For more information about modes, see <span class="enumname"><a href="https://php.net/manual/zh/enum.roundingmode.php" class="enumname">RoundingMode</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.round-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the result as a new <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> object.  </p> </div> <div class="refsect1 errors" id="refsect1-bcmath-number.round-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> if an invalid <span class="parameter" style="color:#3A95FF">mode</span> is specified.  </p> </div> <div class="refsect1 examples" id="refsect1-bcmath-number.round-examples">  <h3 class="title">示例</h3>   <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::round()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">(<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.4'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.5'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.6'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'3.6'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'5.045'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'5.055'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'345'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'345'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'678'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'678'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"3"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"4"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"4"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"4"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#6&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"5.05"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>object(BcMath\Number)#7&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"5.06"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>object(BcMath\Number)#8&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"300"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#9&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#10&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"700"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#11&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"1000"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2     Example of using <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::round()</strong></span> with different <span class="parameter" style="color:#3A95FF">precision</span> values   </strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'123.45'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">1</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(-</span><span style="color: #9876AA">3</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(BcMath\Number)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"123.450"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(3)<br>}<br>object(BcMath\Number)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"123.45"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"123.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"123"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#6&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"120"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#7&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"100"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}<br>object(BcMath\Number)#8&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"0"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-3">   <p><strong>示例 #3     Example of using <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::round()</strong></span> with different <span class="parameter" style="color:#3A95FF">mode</span> values   </strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">echo </span><span style="color: #DD0000">'Rounding modes with 9.5' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'9.5'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfAwayFromZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfTowardsZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfEven</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfOdd</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">TowardsZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">AwayFromZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">NegativeInfinity</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">PositiveInfinity</span><span style="color: #007700">),<br>);<br><br>echo </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>echo </span><span style="color: #DD0000">'Rounding modes with 8.5' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'8.5'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfAwayFromZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfTowardsZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfEven</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">HalfOdd</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">TowardsZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">AwayFromZero</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">NegativeInfinity</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #