: #007700">(<br>    </span><span style="color: #9876AA">\$positive</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">NegativeInfinity</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$negative</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">NegativeInfinity</span><span style="color: #007700">),<br>);<br><br>echo </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br>echo </span><span style="color: #DD0000">'Using RoundingMode::PositiveInfinity with 1 decimal digit precision' </span><span style="color: #007700">. </span><span style="color: #9876AA">PHP_EOL</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$positive</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</span><span style="color: #007700">::</span><span style="color: #9876AA">PositiveInfinity</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$negative</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">round</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">RoundingMode</s