ath\Number)#8&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-1.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br><br>Using&nbsp;RoundingMode::TowardsZero&nbsp;with&nbsp;1&nbsp;decimal&nbsp;digit&nbsp;precision<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"1.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#9&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-1.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br><br>Using&nbsp;RoundingMode::AwayFromZero&nbsp;with&nbsp;1&nbsp;decimal&nbsp;digit&nbsp;precision<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"1.6"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#10&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-1.6"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br><br>Using&nbsp;RoundingMode::NegativeInfinity&nbsp;with&nbsp;1&nbsp;decimal&nbsp;digit&nbsp;precision<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"1.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#11&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-1.6"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br><br>Using&nbsp;RoundingMode::PositiveInfinity&nbsp;with&nbsp;1&nbsp;decimal&nbsp;digit&nbsp;precision<br>object(BcMath\Number)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"1.6"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}<br>object(BcMath\Number)#12&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;string(4)&nbsp;"-1.5"<br>&nbsp;&nbsp;["scale"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.round-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bcround()} - Round arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::ceil()} - Rounds up an arbitrary precision number</span></li>   <li><span class="methodname" style="color:#CC7832">{@link BcMath\Number::floor()} - Rounds down an arbitrary precision number</span></li>  </ul> </div></div>
 */
        public function round(int $precision = 0, \RoundingMode $mode = \RoundingMode::HalfAwayFromZero): Number {}

        /**
 * <div id="bcmath-number.compare" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::compare</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::compare</span> — <span class="dc-title">Compares two arbitrary precision numbers</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.compare-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::compare</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="type BcMath\Number" style="color:#EAB766">BcMath\Number</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$num</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$scale</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Compare two arbitrary precision numbers.   This method behaves similar to the <a href="https://php.net/manual/zh/language.operators.comparison.php" class="link">spaceship operator</a>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.compare-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">num</span></dt>    <dd>     <span class="simpara">      The value to be compared to.     </span>    </dd>            <dt><span class="parameter" style="color:#3A95FF">scale</span></dt>     <dd>      <span class="simpara">       Specify the <span class="parameter" style="color:#3A95FF">scale</span> to use for comparison.       If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, all digits are used in the comparison.      </span>     </dd>      </dl> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.compare-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <span class="literal">0</span> if the two numbers are equal,   <span class="literal">1</span> if <var class="varname">\$this</var> is greater than <span class="parameter" style="color:#3A95FF">num</span>,   <span class="literal">-1</span> otherwise.  </p> </div>  <div class="refsect1 errors" id="refsect1-bcmath-number.compare-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   This method throws a <span class="exceptionname"><a href="https://php.net/manual/zh/class.valueerror.php" class="exceptionname">ValueError</a></span> in the following cases:   </p><ul class="simplelist">    <li><span class="parameter" style="color:#3A95FF">num</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> and not a well-formed BCMath numeric string</li>    <li><span class="parameter" style="color:#3A95FF">scale</span> is outside the valid range</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-bcmath-number.compare-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::compare()</strong></span> example when <span class="parameter" style="color:#3A95FF">scale</span> is not specified</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">)),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.23400'</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.23401'</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(0)<br>int(0)<br>int(-1)<br>int(1)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::compare()</strong></span> example of explicitly specifying <span class="parameter" style="color:#3A95FF">scale</span></strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$number </span><span style="color: #007700">= new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.234'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(new </span><span style="color: #9876AA">BcMath\Number</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.299'</span><span style="color: #007700">), </span><span style="color: #9876AA">1</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.24'</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(</span><span style="color: #DD0000">'1.22'</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">),<br>    </span><span style="color: #9876AA">\$number</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">compare</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">0</span><span style="color: #007700">),<br>);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(0)<br>int(-1)<br>int(1)<br>int(0)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-bcmath-number.compare-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link bccomp()} - 比较两个任意精度的数字</span></li>  </ul> </div></div>
 * 
         * @param Number|int|numeric-string $num
         * @return int Returns -1, 0, or 1
         * @throws \ValueError
         */
        public function compare(Number|string|int $num, ?int $scale = null): int {}

/**
 * <div id="bcmath-number.tostring" class="refentry"> <div class="refnamediv">  <h1 class="refname">BcMath\Number::__toString</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">BcMath\Number::__toString</span> — <span class="dc-title">Converts BcMath\Number to string</span></p> </div> <div class="refsect1 description" id="refsect1-bcmath-number.tostring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>BcMath\Number::__toString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Converts <span class="classname"><a href="https://php.net/manual/zh/class.bcmath-number.php" class="classname">BcMath\Number</a></span> to <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-bcmath-number.tostring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-bcmath-number.tostring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <span class="property">{@link BcMath\Number::value}</span> as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div></div>
 */
